/**
 * Game lines quantitative projection models (NBA / NHL).
 * Interfaces match backend schema generated by nba.game.run_daily and nhl.game.run_daily.
 */

export interface GamePricedMarket {
  system: string
  market_label: string
  side: 'home' | 'away' | 'over' | 'under' | string
  line: number | null
  p_model: number
  push_prob: number
  p_fair: number | null
  p_blended?: number | null
  best_odds: number | null
  best_book: string | null
  n_books: number | null
  model_edge: number | null
  market_ev: number | null
  confluence: boolean
  beezy_score: number
}

export interface GamePricedGame {
  game_key: string
  home_team: string
  away_team: string
  game_date: string
  // NBA specific synthesis
  mu_margin?: number
  sigma_margin?: number
  mu_total?: number
  sigma_total?: number
  exp_pace?: number
  // NHL specific synthesis
  lambda_h?: number
  lambda_a?: number
  exp_total?: number
  // Common markets list
  markets: GamePricedMarket[]
}

export interface GameMetadata {
  game_key: string
  away: string
  home: string
  start: string
}

export interface GameProjectionRow {
  sport: 'nba' | 'nhl' | string
  system: string
  stat: 'spread' | 'total' | 'moneyline' | string
  stat_label: string
  player: string // 'AWAY @ HOME'
  player_norm: string
  team?: string | null
  opp?: string | null
  game_key: string
  commence: string
  side: 'home' | 'away' | 'over' | 'under' | string
  line: number | null
  has_line: boolean
  proj_mean: number | null
  p_model_side: number
  p_mkt_side: number | null
  n_books: number | null
  best_over_odds?: number | null
  best_over_book?: string | null
  best_under_odds?: number | null
  best_under_book?: string | null
  model_edge: number | null
  market_ev: number | null
  confluence: boolean
  beezy_score: number
  push_prob: number
}

export interface GameProjectionsFeed {
  sport: 'nba' | 'nhl' | string
  status: string
  engine: string | null
  as_of: string | null
  age_minutes: number | null
  stale: boolean
  count: number
  rows: GameProjectionRow[]
  priced_games: GamePricedGame[]
  games: GameMetadata[]
  markets: string[]
  locked?: number
}
